import type {ToolDefinition} from '../../types/ai.js';
import {ToolRegistry} from './registry.js';

it('rejects location using the current dynamic schema @specs/hal-engine-tool-input-validation/spec.md#7', async () => {
  const registry = new ToolRegistry();
  let schema: ToolDefinition['inputSchema'] = {
    type: 'object', properties: {location: {type: 'string'}}, required: ['location'],
  };
  const received: Record<string, unknown>[] = [];
  registry.register(
    () => ({name: 'weather', description: 'Weather', inputSchema: schema}),
    async input => {
      received.push(input);
      return JSON.stringify(input);
    }
  );
  const input = {location: 'Berlin'};
  await registry.execute('weather', input);
  schema = {type: 'object', properties: {location: {type: 'number'}}, required: ['location']};
  const response = await registry.execute('weather', input);
  expect({received, result: response.result}).toEqual({
    received: [input], result: expect.stringMatching(/location.*number/),
  });
});
EOF
